<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\Holder\UserGroupMembershipRelyingPartyAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserGroupMembershipRelyingPartyAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserGroupMembershipRelyingPartyAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getRelyingParty returns null on a freshly created holder.
     */
    public function testRelyingPartyNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserGroupMembershipRelyingPartyAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRelyingPartyAssigned());
        $this->assertNull($holder->getRelyingParty());
    }
}
class ImplWithUserGroupMembershipRelyingPartyAttributeHolderUnitTest
{
    use UserGroupMembershipRelyingPartyAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRelyingPartyRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRelyingParty();
    }
}
